export default function FAQ() {
    return (
      <div style={{ maxWidth: 900, margin: "40px auto", padding: 20 }}>
        <h1>FAQ - The Zuro</h1>
  
        <h3>How do I place an order?</h3>
        <p>Select a product → Add to Bag → Checkout → Payment</p>
  
        <h3>What payment methods are available?</h3>
        <p>UPI, Debit Card, Credit Card, Net Banking</p>
  
        <h3>How can I track my order?</h3>
        <p>Go to "Track Orders" page after login</p>
  
        <h3>What is return policy?</h3>
        <p>You can return products within 14 days</p>
      </div>
    );
  }
